def is_decimal(s):
    try:
        Decimal(s)
        return True
    except InvalidOperation:
        return False


def popup(message):
    sg.theme('DarkGrey')
    layout = [[sg.Text(message)]]
    window_popup = sg.Window('', layout, no_titlebar=True, keep_on_top=True, finalize=True)
    return window_popup


def to_shp(file_in):
    """Converts file to ESRI shapefile format using Geopandas"""
    success = False
    try:
        gpd_df = gpd.read_file(file_in)
        if gpd_df.empty:
            print("The file saved is empty, it will be deleted!")
            os.remove(file_in)
        else:
            for geomtype in gpd_df.geom_type.unique():
                 f_out = os.path.splitext(file_in)[0]+'_'+geomtype+'.shp'
                 gpd_df[gpd_df.geom_type == geomtype].to_file(f_out, driver='ESRI Shapefile', layer=geomtype)
            success = True
    except Exception as err:
        print(err)
        print('Stop background task for file:',file_in)
        sys.exit() #stop thread

    return success


# long-running background task
def background_task(target_file):
    # run forever
    while True:
        if os.path.exists(target_file):
                success = to_shp(target_file)
                if success:
                    print('Stop background task for file:',target_file)
                    break
        # block for a while
        sleep(5)


def isTreadAlive():
  for t in threads_monitor:
    if t.is_alive():
      return True
  return False


def get_download_path():
    """Returns the default downloads path for linux or windows"""
    if os.name == 'nt':
        import winreg
        sub_key = r"Software\Microsoft\Windows\CurrentVersion\Explorer\Shell Folders"
        downloads_guid = "{374DE290-123F-4565-9164-39C4925E467B}"
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, sub_key) as key:
            location = winreg.QueryValueEx(key, downloads_guid)[0]
        return location
    else:
        return os.path.join(os.path.expanduser('~'),'Downloads')


# Adapted from PySimpleGUI.org
def convert_to_bytes(file_or_bytes, resize=None):
    '''
    Will convert into bytes and optionally resize an image that is a file or a base64 bytes object.
    Turns into  PNG format in the process so that can be displayed by tkinter
    :param file_or_bytes: either a string filename or a bytes base64 image object
    :type file_or_bytes:  (Union[str, bytes])
    :param resize:  optional new size (max_width, max_height)
    :type resize: (Tuple[int, int] or None)
    :return: (bytes) a byte-string object
    :rtype: (bytes)
    '''
    if isinstance(file_or_bytes, str):
        img = PIL.Image.open(file_or_bytes)
    else:
        try:
            img = PIL.Image.open(io.BytesIO(base64.b64decode(file_or_bytes)))
        except Exception as e:
            dataBytesIO = io.BytesIO(file_or_bytes)
            img = PIL.Image.open(dataBytesIO)
    
    if img._getexif() == None and isinstance(file_or_bytes, str):
        return "NO_EXIF" 

    if resize:
        img.thumbnail(resize, PIL.Image.Resampling.LANCZOS) #preserve aspect ratio
        
    with io.BytesIO() as bio:
        img.save(bio, format="PNG")
        del img
        return bio.getvalue()
    
    
def load_map_tool(file_in):
    root_path = os.path.dirname(file_in)
    fname_json = os.path.join(root_path,'info.json')
    if os.path.exists(fname_json):
        with open(fname_json,'r') as f_json:
                flight_info = json.load(f_json)     
    else:
        flight_info_form = [[sg.Frame('Flight auxiliaries information',
                                    [[sg.Text('Flight height (meters):', size=(23, 1)), sg.InputText(key='-f_height-')],
                                              [sg.Text('Course angle (degrees):', size=(23, 1)), sg.InputText(key='-f_course_angle-')],
                                              [sg.Text('Sensor width (millimeters):', size=(23, 1)), sg.InputText(key='-s_size_w-')],
                                              [sg.Button('OK'), sg.Button('Cancel')]], pad=(0,0))]]
        
        window_form = sg.Window('Flight information form', flight_info_form, finalize=True, keep_on_top=True)
        while True:
            event_form, values_form = window_form.read()
            if event_form == "Exit" or event_form == sg.WIN_CLOSED or event_form == 'Cancel':
                break
            elif event_form == 'OK':
                if is_decimal(values_form['-f_height-']) and is_decimal(values_form['-f_course_angle-']) and is_decimal(values_form['-s_size_w-']):
                    flight_info = {'flight_height_m':float(values_form['-f_height-']),
                                   'course_angle_degrees':float(values_form['-f_course_angle-']),
                                   'sensor_width_mm':float(values_form['-s_size_w-'])}
                    
                    ch = sg.popup_yes_no("Do you want to save this auxiliary information for all images in this folder?", keep_on_top=True, title="Ask confirmation")
                    if ch == 'Yes':
                          with open(fname_json, 'w', encoding='utf-8') as outfile:
                               outfile.write(json.dumps(flight_info, indent=4))
                    break
                else:
                    sg.popup_auto_close('Please, fill the information required!')

        window_form.close()

    if 'flight_info' in locals():
        popup_win = popup("Launching the map application to get samples, please wait...")
        popup_win.refresh()
        popup_win.force_focus()
        samples_file_output = create_map(file_in,flight_info) #Launch the map application to get samples
        popup_win.close()
        sg.popup_auto_close("The application has been successfully launched in your default browser!", keep_on_top=True, title='Information')
        sg.theme(theme)
       
        # Monitoring until the file with samples is saved:
        target_file = os.path.join(get_download_path(),samples_file_output)
        print('Starting background task...')
        daemon = Thread(target=background_task, args=(target_file,), daemon=True, name='Monitor')
        threads_monitor.append(daemon)
        daemon.start()

    
 
